-- Skyline Smash: the roster, for unlock picks, featured players and career recruiting. Written by npm run roster:check.
-- Run it in Supabase → SQL Editor after changing the roster (after 2.7-ranks.sql and career.sql). Safe to run again.
alter table public.characters add column if not exists country text, add column if not exists released_in text, add column if not exists career_strength int;
on conflict (id) do update set name = excluded.name, rarity = excluded.rarity, enabled = excluded.enabled,
  country = excluded.country, released_in = excluded.released_in, career_strength = excluded.career_strength;
update public.characters set enabled = false where id not in ('default_player', 'dritan_berisha', 'facundo_fernandez', 'jonas_baxter', 'kieran_sterling', 'lucan_halden', 'milan_kessler', 'pavel_varden', 'quentin_marlow', 'ronan_caldwell', 'ulric_whitaker', 'wilfred_xander', 'lukas_steiner', 'kamran_aliyev', 'noah_peeters', 'tanvir_rahman', 'jassim_aldoseri', 'cassian_galen', 'jalen_fenwick', 'milan_caldwell', 'xavier_zoric', 'yarden_upton', 'denzel_larkin', 'gavin_weller', 'isak_galen', 'orin_ashford', 'ronan_granger', 'yuri_arden', 'yuri_granger', 'bastian_jorvik', 'harlan_roth', 'ivo_ashford', 'ivo_weller', 'kellan_kessler', 'lucan_lowell', 'milan_underwood', 'nerio_tolland', 'nolan_jensen', 'quentin_everett', 'rafael_dale', 'soren_marlow', 'tavian_norwood', 'tomas_arden', 'tomas_granger', 'viggo_norwood', 'wesley_whitaker', 'xavier_larkin', 'xavier_radley', 'yarden_iverson', 'yuri_sable', 'stavros_ioannou', 'denzel_pryce', 'emric_galen', 'emric_yarrow', 'oskar_kessler', 'quentin_sterling', 'viggo_zoric', 'soren_everett', 'wesley_corvin', 'zev_bellamy', 'alden_keaton', 'kieran_ashford', 'silas_farrow', 'tavian_hollis', 'xavier_hollis', 'dawit_bekele', 'aaro_makinen', 'bastian_norden', 'darian_thorne', 'felix_norden', 'nerio_farrow', 'oskar_orwell', 'quentin_whitaker', 'rafael_norwood', 'zev_jorvik', 'adrian_maddox', 'alden_sable', 'calder_keaton', 'calder_weller', 'jonas_pryce', 'kellan_quade', 'lennox_dale', 'perrin_tolland', 'silas_xander', 'soren_whitaker', 'kojo_owusu', 'luis_lopez', 'brennan_dunley', 'darian_bellamy', 'denzel_vale', 'mate_nagy', 'adrian_upton', 'elias_keaton', 'florian_vale', 'gavin_eldric', 'isak_yarrow', 'jalen_jensen', 'jalen_roth', 'lucan_baxter', 'lucan_tolland', 'marek_marlow', 'nerio_lowell', 'pavel_norwood', 'perrin_farrow', 'ronan_underwood', 'tomas_orwell', 'ulric_iverson', 'urian_xander', 'wesley_iverson', 'wesley_quillon', 'emric_maddox', 'florian_dunley', 'marek_ashford', 'nolan_dale', 'orin_everett', 'orin_sterling', 'oskar_unde